// EQUIPMENT NAME NORMALISATION
// Treats TTLI-1/TTLI1/TTlLI1 as same; HCM-1/HCM1 as same etc.
// ═══════════════════════════════════════════════════════════
function normalizeEquipment(name){
  if(!name || name === 'nan') return name;
  // Remove spaces around hyphens, then normalise known prefixes
  let n = String(name).trim();
  // Fix common typos: TTlLI → TTLI (case variants)
  n = n.replace(/TTlLI/gi, 'TTLI').replace(/TLLI/gi, 'TTLI');
  // Strip hyphens between prefix and number: TTLI-1 → TTLI1, HCM-2 → HCM2, DU-R → DUR etc.
  // But only for known machine families
  const families = ['TTLI','HCM','HRM','TTM','BLT','TBT','DU'];
  for(const f of families){
    const re = new RegExp('^' + f + '[\\-\\s]+', 'i');
    if(re.test(n)){
      n = n.replace(/[-\s]+/, ''); // remove ALL hyphens/spaces after prefix match
      // Re-uppercase the prefix
      n = f + n.slice(f.length);
      break;
    }
  }
  return n;
}

// Apply normalisation to every row's Equipment field
ALL_ROWS.forEach(r => {
  if(r['Equipment']) r['Equipment'] = normalizeEquipment(r['Equipment']);
});


