// HELPERS
// ═══════════════════════════════════════════════════════════
const uniq   = (arr, k) => [...new Set(arr.map(r => r[k]).filter(Boolean))].sort();
const sumBy  = (arr, k) => arr.reduce((a, r) => a + (+r[k] || 0), 0);
const gsum   = (arr, k, v) => { const m = {}; arr.forEach(r => { if(!r[k]) return; m[r[k]] = (m[r[k]]||0) + (+r[v]||0); }); return m; };
const gcount = (arr, k)    => { const m = {}; arr.forEach(r => { if(!r[k]) return; m[r[k]] = (m[r[k]]||0) + 1;            }); return m; };
const srtd   = (obj, desc=true) => Object.entries(obj).sort((a,b) => desc ? b[1]-a[1] : a[1]-b[1]);
const fmt    = n => n >= 1000 ? (n/1000).toFixed(1)+'k' : String(n);
const metricData = (arr, key) => METRIC === 'downtime' ? gsum(arr, key, 'Equipment Downtime') : gcount(arr, key);
const metricLabel = () => METRIC === 'downtime' ? 'Downtime (min)' : 'No. of Losses';

