// ═══════════════════════════════════════════════════════════
// FILTERS
// ═══════════════════════════════════════════════════════════
function fillSelect(id, values, curVal){
  const s = document.getElementById(id);
  const prev = curVal !== undefined ? curVal : s.value;
  while(s.options.length > 1) s.remove(1);
  values.forEach(v => {
    const o = document.createElement('option');
    o.value = v; o.textContent = v.replace(/_/g,' ');
    if(v === prev) o.selected = true;
    s.appendChild(o);
  });
}

function applyFilters(){
  const m  = document.getElementById('f-month').value;
  const op = document.getElementById('f-op').value;
  const eq = document.getElementById('f-eq').value;
  const lc = document.getElementById('f-lc').value;

  ROWS = CURRENT_DATA.filter(r =>
    (!m  || r['Month']         === m)  &&
    (!op || r['Operation']     === op) &&
    (!eq || r['Equipment']     === eq) &&
    (!lc || r['Loss Category'] === lc)
  );
  renderAll();
}

function initFilters(rows){
  fillSelect('f-month', uniq(rows,'Month'));
  fillSelect('f-op',    uniq(rows,'Operation'));
  fillSelect('f-eq',    uniq(rows,'Equipment'));
  fillSelect('f-lc',    uniq(rows,'Loss Category'));

  // Reset values
  ['f-month','f-op','f-eq','f-lc'].forEach(id => document.getElementById(id).value = '');

  // Wire events (use onchange to avoid duplicates)
  document.getElementById('f-month').onchange = applyFilters;
  document.getElementById('f-op').onchange    = applyFilters;
  document.getElementById('f-eq').onchange    = applyFilters;
  document.getElementById('f-lc').onchange    = applyFilters;
}

function setMetric(mode){
  METRIC = mode;
  document.getElementById('btn-dt').classList.toggle('active', mode==='downtime');
  document.getElementById('btn-ev').classList.toggle('active', mode==='events');
  document.getElementById('metric-hint').textContent =
    mode==='downtime' ? 'Equipment Downtime (minutes)' : 'Number of Loss Events';
  renderAll();
}

function setTrendView(view){
  TREND_VIEW = view;
  renderMonthly();
}

// ═══════════════════════════════════════════════════════════
// RENDER FUNCTIONS
// ═══════════════════════════════════════════════════════════
function renderKPI(){
  const pl = ROWS.filter(r => r['Loss Category']==='Planned_Loss');
  const un = ROWS.filter(r => r['Loss Category']==='Unplanned_Loss');
  const total = ROWS.length;
  const eqDt = sumBy(ROWS,'Equipment Downtime');
  const lnDt = sumBy(ROWS,'line downtime');
  const kpis = [
    {k:'Total Loss Events',    v:total,                                       c:'c-violet'},
    {k:'Planned Events',       v:pl.length,                                   c:'c-green'},
    {k:'Unplanned Events',     v:un.length,                                   c:'c-red'},
    {k:'Planned Loss %',       v:total?(pl.length/total*100).toFixed(1)+'%':'0%', c:'c-green'},
    {k:'Unplanned Loss %',     v:total?(un.length/total*100).toFixed(1)+'%':'0%', c:'c-red'},
    {k:'Equip. Downtime (min)',v:eqDt.toLocaleString(),                       c:'c-amber'},
    {k:'Line Downtime (min)',  v:lnDt.toLocaleString(),                       c:'c-pink'},
    {k:'Operations',           v:uniq(ROWS,'Operation').length,               c:'c-violet'},
    {k:'Equipment',            v:uniq(ROWS,'Equipment').length,               c:'c-indigo'},
  ];
  document.getElementById('kpi-grid').innerHTML = kpis.map(k =>
    `<div class="kpi-card"><div class="kk">${k.k}</div><div class="vv ${k.c}">${k.v}</div></div>`
  ).join('');
}

function renderMonthly(){
  const monthFilter = document.getElementById('f-month').value;
  const card = document.getElementById('row-donut-monthly');
  const isDaily = TREND_VIEW==='daily';

  // Monthly trend across many months isn't meaningful once a single month is
  // selected; daily view still works fine (it just narrows to that month's days).
  if(!isDaily && monthFilter){ card.style.display='none'; return; }
  card.style.display='';

  const isDT = METRIC==='downtime';
  const get = (arr) => isDT ? sumBy(arr,'Equipment Downtime') : arr.length;

  const labels = isDaily ? uniq(ROWS,'Date').sort() : uniq(ROWS,'Month');
  const key = isDaily ? 'Date' : 'Month';
  const planArr = labels.map(l => get(ROWS.filter(r=>r[key]===l&&r['Loss Category']==='Planned_Loss')));
  const unArr   = labels.map(l => get(ROWS.filter(r=>r[key]===l&&r['Loss Category']==='Unplanned_Loss')));
  const totArr  = labels.map((_,i) => planArr[i]+unArr[i]);

  document.getElementById('sub-monthly').textContent =
    isDaily ? 'Planned vs Unplanned by day' : 'Planned vs Unplanned by month';

  mkChart('c-monthly','line',{
    labels,
    datasets:[
      {label:'Total',    data:totArr, borderColor:'#8b5cf6',backgroundColor:'rgba(139,92,246,.1)',fill:true,tension:.3,pointRadius:isDaily?2:4},
      {label:'Planned',  data:planArr,borderColor:'#34d399',borderDash:[5,3],tension:.3,pointRadius:isDaily?1:3},
      {label:'Unplanned',data:unArr,  borderColor:'#f87171',borderDash:[5,3],tension:.3,pointRadius:isDaily?1:3},
    ]
  },{plugins:{legend:{labels:{color:'#655d85',font:{size:11}}}},scales:gridOpts});
}

function renderOp(){
  const eqFilter = document.getElementById('f-eq').value;
  const opFilter = document.getElementById('f-op').value;
  const card = document.getElementById('card-op');
  const row  = document.getElementById('row-op-eq');
  if(eqFilter || opFilter){ card.style.display='none'; row.classList.add('single'); return; }
  card.style.display=''; row.classList.remove('single');

  const data = srtd(metricData(ROWS,'Operation')).slice(0,12);
  document.getElementById('sub-op').textContent = 'Ranked by ' + metricLabel();
  mkChart('c-op','bar',{
    labels:data.map(x=>x[0]),
    datasets:[{label:metricLabel(),data:data.map(x=>x[1]),
      backgroundColor:data.map((_,i)=>i<3?'#f87171':i<6?'#fbbf24':'#8b5cf6'),borderRadius:4,borderSkipped:false}]
  },{indexAxis:'y',plugins:{legend:{display:false}},scales:gridOptsH});
}

function renderEq(){
  const data = srtd(metricData(ROWS,'Equipment')).slice(0,15);
  document.getElementById('sub-eq').textContent = 'Top 15 by ' + metricLabel();
  mkChart('c-eq','bar',{
    labels:data.map(x=>x[0]),
    datasets:[{label:metricLabel(),data:data.map(x=>x[1]),
      backgroundColor:data.map((_,i)=>i<3?'#f87171':i<6?'#fbbf24':'#34d399'),borderRadius:4,borderSkipped:false}]
  },{indexAxis:'y',plugins:{legend:{display:false}},scales:gridOptsH});
}

function renderLT(){
  const data = srtd(metricData(ROWS,'Loss Type'));
  mkChart('c-lt','bar',{
    labels:data.map(x=>x[0].replace(/_/g,' ')),
    datasets:[{label:metricLabel(),data:data.map(x=>x[1]),
      backgroundColor:data.map(x=>TYPE_COL[x[0]]||'#8b5cf6'),borderRadius:4,borderSkipped:false}]
  },{indexAxis:'y',plugins:{legend:{display:false}},scales:gridOptsH});
}

function renderFail(){
  const data = srtd(metricData(ROWS,'Failure Description Norm')).slice(0,15);
  mkChart('c-fail','bar',{
    labels:data.map(x=>x[0].length>42?x[0].slice(0,40)+'…':x[0]),
    datasets:[{label:metricLabel(),data:data.map(x=>x[1]),
      backgroundColor:data.map((_,i)=>i<3?'#f87171':i<6?'#fbbf24':'#8b5cf6'),borderRadius:3,borderSkipped:false}]
  },{indexAxis:'y',plugins:{legend:{display:false}},scales:{...gridOptsH,y:{ticks:{color:'#221f36',font:{size:10}},grid:{color:'#ece9f7'}}}});
}

function renderPareto(){
  const data  = srtd(metricData(ROWS,'Failure Description Norm')).slice(0,20);
  const total = data.reduce((a,x)=>a+x[1],0);
  let cum=0;
  const cumPct = data.map(x=>{ cum+=x[1]; return +(cum/total*100).toFixed(1); });
  mkChart('c-pareto','bar',{
    labels:data.map(x=>x[0].length>20?x[0].slice(0,18)+'…':x[0]),
    datasets:[
      {label:metricLabel(),data:data.map(x=>x[1]),backgroundColor:'#7c3aed',borderRadius:3,yAxisID:'y'},
      {label:'Cumulative %',data:cumPct,type:'line',borderColor:'#f87171',backgroundColor:'transparent',yAxisID:'y1',tension:.3,pointRadius:3}
    ]
  },{
    plugins:{legend:{labels:{color:'#655d85',font:{size:11}}}},
    scales:{
      x:{ticks:{color:'#655d85',font:{size:9}},grid:{color:'#ece9f7'}},
      y:{ticks:{color:'#655d85'},grid:{color:'#ece9f7'}},
      y1:{position:'right',min:0,max:100,ticks:{color:'#dc2626',callback:v=>v+'%'},grid:{display:false}}
    }
  });
}

function renderStacked(){
  const topEq  = srtd(gsum(ROWS,'Equipment','Equipment Downtime')).slice(0,12).map(x=>x[0]);
  const lts    = uniq(ROWS,'Loss Type');
  const datasets = lts.map((lt,i)=>({
    label:lt.replace(/_/g,' '),
    backgroundColor:TYPE_COL[lt]||PALETTE[i%PALETTE.length],
    data:topEq.map(eq=>METRIC==='downtime'
      ? sumBy(ROWS.filter(r=>r.Equipment===eq&&r['Loss Type']===lt),'Equipment Downtime')
      : ROWS.filter(r=>r.Equipment===eq&&r['Loss Type']===lt).length)
  }));
  mkChart('c-stacked','bar',{labels:topEq,datasets},{
    plugins:{legend:{labels:{color:'#655d85',font:{size:10}}}},
    scales:{
      x:{stacked:true,ticks:{color:'#655d85',font:{size:10}},grid:{color:'#ece9f7'}},
      y:{stacked:true,ticks:{color:'#655d85'},grid:{color:'#ece9f7'}}
    }
  });
}

function renderPriority(){
  const data = srtd(metricData(ROWS,'Equipment')).slice(0,10);
  const unit = METRIC==='downtime' ? ' min' : ' losses';
  document.getElementById('priority').innerHTML = data.map(([eq,v],i)=>`
    <li class="prio-item">
      <div class="prio-rank ${i<3?'top':''}">${i+1}</div>
      <span class="prio-name">${eq}</span>
      <span class="prio-val">${v.toLocaleString()}${unit}</span>
    </li>`).join('');
}

function renderAll(){
  renderKPI();
  renderMonthly();
  renderOp();
  renderEq();
  renderLT();
  renderFail();
  renderPareto();
  renderStacked();
  renderPriority();
}

// ═══════════════════════════════════════════════════════════
// BOOT
// ═══════════════════════════════════════════════════════════
function bootDashboard(rows){
  rows = rows.filter(r => {
    const eq = (r['Equipment']||'').trim().toLowerCase();
    return eq !== 'full line' && eq !== 'hcm';
  });
  CURRENT_DATA = rows;
  initFilters(rows);
  ROWS = [...rows];
  METRIC = 'downtime';
  document.getElementById('btn-dt').classList.add('active');
  document.getElementById('btn-ev').classList.remove('active');
  document.getElementById('metric-hint').textContent = 'Equipment Downtime (minutes)';
  renderAll();
  // scroll progress
  window.onscroll = () => {
    const pct = window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;
    document.getElementById('progress-fill').style.width = pct+'%';
  };
}

// ── Boot with embedded data immediately ─────────────────────────
(function(){
  document.getElementById('upload-screen').style.display = 'none';
  document.getElementById('dashboard').style.display = 'block';
  bootDashboard(ALL_ROWS);
})();

// ═══════════════════════════════════════════════════════════
// UPLOAD LOGIC
// ═══════════════════════════════════════════════════════════
function showUpload(){
  document.getElementById('upload-screen').style.display = 'flex';
  document.getElementById('dashboard').style.display = 'none';
  document.getElementById('upl-err').textContent = '';
  document.getElementById('upl-prog').textContent = '';
  document.getElementById('file-input').value = '';
  document.getElementById('onedrive-link').value = '';
  Object.values(CHARTS).forEach(c=>{ try{c.destroy();}catch(e){} });
}

function processFile(file){
  document.getElementById('upl-err').textContent = '';
  document.getElementById('upl-prog').textContent = '⏳ Reading…';
  const reader = new FileReader();
  reader.onload = function(e){ parseWorkbookBuffer(e.target.result); };
  reader.readAsArrayBuffer(file);
}

function parseWorkbookBuffer(buffer){
  try{
    document.getElementById('upl-prog').textContent = '⏳ Parsing…';
    const wb  = XLSX.read(new Uint8Array(buffer),{type:'array',cellDates:true});

    const COL = {'date':'Date','operation':'Operation','equipment':'Equipment',
      'failure description':'Failure Description','loss category':'Loss Category',
      'loss type':'Loss Type','equipment downtime':'Equipment Downtime','line downtime':'line downtime'};
    const req = ['Operation','Equipment','Loss Category','Loss Type','Equipment Downtime'];

    // Scan every sheet in the workbook and use the first one that actually
    // contains the columns we need — a workbook can have many helper/lookup
    // sheets before the real data sheet, so we can't just assume sheet #1.
    let raw = null, norm = null, missBest = req, sheetUsed = null;
    for(const name of wb.SheetNames){
      const ws  = wb.Sheets[name];
      const rws = XLSX.utils.sheet_to_json(ws,{defval:''});
      if(!rws.length) continue;
      const nrm = rws.map(r=>{
        const o={};
        Object.keys(r).forEach(k=>{ o[COL[k.trim().toLowerCase()]||k.trim()]=r[k]; });
        return o;
      });
      const miss = req.filter(c=>!(c in (nrm[0]||{})));
      if(miss.length < missBest.length){ missBest = miss; }
      if(!miss.length){ raw = rws; norm = nrm; sheetUsed = name; break; }
    }

    if(!norm){
      document.getElementById('upl-err').textContent =
        'Missing: '+missBest.join(', ')+' (checked '+wb.SheetNames.length+' sheet(s): '+wb.SheetNames.join(', ')+')';
      document.getElementById('upl-prog').textContent='';
      return;
    }
    if(!raw.length){ document.getElementById('upl-err').textContent='File is empty.'; document.getElementById('upl-prog').textContent=''; return; }

    document.getElementById('upl-prog').textContent = '⚙️ Processing '+raw.length+' rows…';
    const processed = norm.map(r=>{
      let month='';
      if(r['Date']){ const d=r['Date'] instanceof Date?r['Date']:new Date(r['Date']); if(!isNaN(d)) month=d.toISOString().slice(0,7); }
      return {...r,'Equipment Downtime':parseFloat(r['Equipment Downtime'])||0,'line downtime':parseFloat(r['line downtime'])||0,Month:month};
    }).filter(r=>r['Loss Category']&&r['Operation']);

    if(!processed.length){ document.getElementById('upl-err').textContent='No valid rows found.'; document.getElementById('upl-prog').textContent=''; return; }

    document.getElementById('upl-prog').textContent='';
    // Normalise equipment names in uploaded data
    processed.forEach(r => { if(r['Equipment']) r['Equipment'] = normalizeEquipment(r['Equipment']); });
    // Normalise Failure Description text (same map used for the built-in dataset)
    // so Top-15 Failure Descriptions / Pareto charts (which group on this key) work for uploads too.
    processed.forEach(r => {
      const d = r['Failure Description'];
      if (d) r['Failure Description Norm'] = FAIL_NORM[d.trim()] || d.trim();
    });
    document.getElementById('upload-screen').style.display='none';
    document.getElementById('dashboard').style.display='block';
    bootDashboard(processed);

  }catch(err){
    document.getElementById('upl-err').textContent='Error: '+err.message;
    document.getElementById('upl-prog').textContent='';
    console.error(err);
  }
}

// Converts a OneDrive/SharePoint share link into a direct-download URL.
function toOneDriveDirectLink(url){
  url = url.trim();
  if(/1drv\.ms|onedrive\.live\.com/i.test(url)){
    // Personal OneDrive share links: forcing download via query param
    if(/[?&]download=1/i.test(url)) return url;
    return url + (url.includes('?') ? '&' : '?') + 'download=1';
  }
  if(/sharepoint\.com/i.test(url)){
    // SharePoint/OneDrive for Business share links
    if(/[?&]download=1/i.test(url)) return url;
    return url + (url.includes('?') ? '&' : '?') + 'download=1';
  }
  return url; // fall back to as-is (e.g. already a direct file URL)
}

function loadFromOneDrive(){
  const input = document.getElementById('onedrive-link');
  const url = input.value.trim();
  document.getElementById('upl-err').textContent = '';
  if(!url){ document.getElementById('upl-err').textContent = 'Paste a OneDrive link first.'; return; }

  document.getElementById('upl-prog').textContent = '⏳ Fetching from OneDrive…';
  const directUrl = toOneDriveDirectLink(url);

  fetch(directUrl)
    .then(res => {
      if(!res.ok) throw new Error('HTTP '+res.status);
      return res.arrayBuffer();
    })
    .then(buffer => parseWorkbookBuffer(buffer))
    .catch(err => {
      document.getElementById('upl-prog').textContent = '';
      document.getElementById('upl-err').textContent =
        'Could not load link (it may need to be a public "Anyone with the link" share, or the host blocks direct access). ' + err.message;
      console.error(err);
    });
}



const dz = document.getElementById('drop-zone');
dz.addEventListener('dragover',  e=>{ e.preventDefault(); dz.classList.add('drag'); });
dz.addEventListener('dragleave', ()=> dz.classList.remove('drag'));
dz.addEventListener('drop',      e=>{ e.preventDefault(); dz.classList.remove('drag'); if(e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]); });
document.getElementById('file-input').addEventListener('change', e=>{ if(e.target.files[0]) processFile(e.target.files[0]); });

